"use client";
import { useReducedMotion } from "motion/react";
import dynamic from "next/dynamic";

/* Loaded on demand: the dotLottie player chunk and its WASM are not part of the first paint. */
const DotLottieReact = dynamic(() => import("@lottiefiles/dotlottie-react").then((m) => m.DotLottieReact), {
  ssr: false,
});

/** Lottie vinyl (public/anim/vinyl.json, generated by scripts/make-lottie.ts). Fills its parent; spins only while composing. */
export function Vinyl({ playing = true, className = "" }: { playing?: boolean; className?: string }) {
  const reduced = useReducedMotion();
  return (
    <div className={`relative aspect-square ${className}`} aria-hidden>
      <DotLottieReact
        src="/anim/vinyl.json"
        loop
        autoplay={playing && !reduced}
        style={{ width: "100%", height: "100%" }}
      />
    </div>
  );
}
